import math, copy, bisect

class RefPkt:
    def __init__(self,id,flow,length,flow_size,rank,ordinal,bank):
        self.id=id; self.flow=flow; self.length=length; self.flow_size=flow_size
        self.rank=rank; self.ordinal=ordinal; self.bank=bank
        self.key=(rank,ordinal); self.lag=0
    def __repr__(self): return f'P({self.id},{self.rank},{self.ordinal},{self.bank},{self.lag})'

class RefEngine:
    def __init__(self,run):
        self.M=run['banks']; self.L=run['load_balancers']; self.fcap=run['fifo_bytes']; self.pcap=run['pifo_bytes']
        self.batch=run['refill_batch']; self.P=run['sample_period']; self.borders=list(run['borders'])
        R=len(self.borders)-1
        self.C=[[[1 if q<(r%self.M) else 0 for r in range(R)] for q in range(self.M)] for _ in range(self.L)]
        self.H=[0]*R
        self.t=0; self.l=0; self.p=0; self.a=0
        self.fifos=[[] for _ in range(self.M)] # pkt list ordinal
        self.pifos=[[] for _ in range(self.M)] # sorted key
        self.live={} # id -> pkt
        self.pol=copy.deepcopy(run['policy'])
        self.log=[]
        if self.pol['kind']=='wfq':
            self.weights=dict(self.pol['weights']); self.finish={f:0 for f,w in self.pol['weights']}; self.V=0
        elif self.pol['kind']=='sp':
            self.levels=dict(self.pol['levels'])
        elif self.pol['kind']=='fifo': self.ftime=0
        self.slots={}
    def rank_attempt(self,fid,length,fs):
        k=self.pol['kind']
        if k=='fifo':
            self.ftime+=1; return self.ftime
        if k=='sp': return self.levels[fid]
        if k=='sff': return fs
        if k=='wfq':
            w=self.weights[fid]
            old=self.finish[fid]
            base=max(old,self.V)
            nf=base+(length*1048576+w-1)//w
            self.finish[fid]=nf; return nf
    def service(self,rank):
        if self.pol['kind']=='wfq': self.V=max(self.V,rank)
    def range_index(self,rank):
        x=rank
        U=self.borders[-1]
        if x>=U: x=U-1
        if x<self.borders[0]: x=self.borders[0]
        return bisect.bisect_right(self.borders,x)-1
    def sample(self):
        R=len(self.H); X=[0]*R
        for lb in self.C:
            for q in range(self.M):
                for r in range(R): X[r]+=lb[q][r]
        for lb in self.C:
            for q in range(self.M):
                # wait fixed (l,r) row subtract min over q
                pass
        # do per l,r
        for li in range(self.L):
            for r in range(R):
                mn=min(self.C[li][q][r] for q in range(self.M))
                if mn:
                    for q in range(self.M): self.C[li][q][r]-=mn
        H=[self.H[r]//2+X[r] for r in range(R)]
        self.H=H; self.a=0
        return X,H
    def migrate(self,vec,oldb,newb):
        nr=len(newb)-1; res=[0]*nr
        for j,m in enumerate(vec):
            if m==0: continue
            b=oldb[j]; c=oldb[j+1]; d=c-b
            F=[]
            for x in newb:
                t=x-b
                if t<=0: F.append(0)
                elif t>=d: F.append(m)
                else: F.append((m*t)//d)
            for k in range(nr): res[k]+=F[k+1]-F[k]
        return res
    def enqueue(self,i,e):
        _,id,fid,length,fs=e
        rank=self.rank_attempt(fid,length,fs)
        r=self.range_index(rank)
        used=self.l; self.l=(self.l+1)%self.L
        counts=[self.C[used][q][r] for q in range(self.M)]
        q=min(range(self.M), key=lambda x:(counts[x],x))
        usedbytes=sum(p.length for p in self.fifos[q])
        accepted=usedbytes+length<=self.fcap
        if accepted:
            p=RefPkt(id,fid,length,fs,rank,i,q)
            self.fifos[q].append(p); self.live[id]=p
            self.C[used][q][r]+=1; self.a+=1
        self.log.append([i,'enqueue',id,rank,used,r,q,accepted])
        if accepted and self.a==self.P:
            X,H=self.sample(); self.log.append([i,'sample',X,H])
    def refill(self,q):
        moved=self.fifos[q][:self.batch]
        self.fifos[q]=self.fifos[q][self.batch:]
        cand=self.pifos[q]+moved
        cand.sort(key=lambda p:p.key)
        total=0; keep=0
        for p in cand:
            if total+p.length<=self.pcap:
                total+=p.length; keep+=1
            else: break
        retained=cand[:keep]; evicted=cand[keep:]
        self.pifos[q]=retained
        ev=[]
        for p in reversed(evicted):
            del self.live[p.id]
            ev.append(p.id)
        return ev
    def dequeue(self,i,n):
        for _ in range(n):
            oldt=self.t; q=self.p; self.p=(q+1)%self.M; self.t+=1
            ev=[]; served=None
            if self.pifos[q]:
                served=self.pifos[q].pop(0)
                self.live.pop(served.id,None)
                self.service(served.rank)
                ev=self.refill(q)
            else:
                ev=self.refill(q)
                if self.pifos[q]:
                    served=self.pifos[q].pop(0)
                    self.live.pop(served.id,None)
                    self.service(served.rank)
            if served is None:
                self.log.append([i,'dequeue',oldt,q,None,None,0,0,ev])
            else:
                lag=served.lag
                err=sum(1 for p in self.live.values() if p.rank<served.rank)
                for p in self.live.values():
                    if p.rank<served.rank: p.lag+=1
                self.log.append([i,'dequeue',oldt,q,served.id,served.rank,err,lag,ev])
    def cancel(self,i,id):
        p=self.live.get(id)
        if p is None:
            self.log.append([i,'cancel',id,None,None,None]); return
        q=p.bank
        try:
            self.fifos[q].remove(p); stage='fifo'
        except ValueError:
            self.pifos[q].remove(p); stage='pifo'
        del self.live[id]
        self.log.append([i,'cancel',id,stage,q,p.lag])
    def inspect(self,i,id):
        p=self.live.get(id)
        if p is None: rec=None
        else:
            if p in self.fifos[p.bank]: stage='fifo'
            elif p in self.pifos[p.bank]: stage='pifo'
            else: raise Exception('lost')
            rec=[p.rank,p.bank,stage,p.length,p.flow,p.lag]
        self.log.append([i,'inspect',id,rec])
    def weight(self,i,fid,w):
        if self.pol['kind']=='wfq': self.weights[fid]=w
        self.log.append([i,'weight',fid,w])
    def snap(self):
        # store actual objects deep copy; log not
        return copy.deepcopy((self.t,self.l,self.p,self.a,self.borders,self.C,self.H,self.fifos,self.pifos,self.live,self.slots.copy(),
                              getattr(self,'ftime',None),getattr(self,'V',None),getattr(self,'weights',None),getattr(self,'finish',None)))
    def restore(self,i,name):
        (self.t,self.l,self.p,self.a,self.borders,self.C,self.H,self.fifos,self.pifos,self.live,slots,
         ftime,V,weights,finish)=copy.deepcopy(self.slots[name])
        self.slots=slots
        if self.pol['kind']=='fifo': self.ftime=ftime
        if self.pol['kind']=='wfq': self.V=V; self.weights=weights; self.finish=finish
        self.log.append([i,'restore',name])
    def save(self,i,name):
        self.slots[name]=self.snap(); self.log.append([i,'save',name])
    def state(self):
        qs=[]
        for q in range(self.M):
            qs.append({'fifo':[p.id for p in self.fifos[q]],'pifo':[p.id for p in self.pifos[q]],
                       'fifo_bytes':sum(p.length for p in self.fifos[q]),'pifo_bytes':sum(p.length for p in self.pifos[q])})
        lags=sorted([[id,p.lag] for id,p in self.live.items()])
        if self.pol['kind']=='fifo': pc={'kind':'fifo','time':self.ftime}
        elif self.pol['kind']=='sp': pc={'kind':'sp','levels':sorted([list(x) for x in self.pol['levels']])}
        elif self.pol['kind']=='sff': pc={'kind':'sff'}
        else:
            pc={'kind':'wfq','virtual_time':self.V,
                'weights':[[f,self.weights[f]] for f in sorted(self.weights)],
                'finish':[[f,self.finish[f]] for f in sorted(self.finish)]}
        return {'tick':self.t,'load_balancer':self.l,'service_bank':self.p,'sample_progress':self.a,
                'borders':self.borders[:],'counters':self.C,'history':self.H,'policy':pc,'queues':qs,'lags':lags}
    def run(self,events):
        for i,e in enumerate(events):
            c=e[0]
            if c=='enqueue': self.enqueue(i,e)
            elif c=='dequeue': self.dequeue(i,e[1])
            elif c=='sample':
                X,H=self.sample(); self.log.append([i,'sample',X,H])
            elif c=='repartition':
                nb=e[1]; ob=self.borders
                nc=[[self.migrate(row,ob,nb) for row in lb] for lb in self.C]
                nh=self.migrate(self.H,ob,nb)
                self.C=nc; self.H=nh; self.borders=list(nb)
                self.log.append([i,'repartition',len(nb)-1])
            elif c=='cancel': self.cancel(i,e[1])
            elif c=='inspect': self.inspect(i,e[1])
            elif c=='weight': self.weight(i,e[1],e[2])
            elif c=='save': self.save(i,e[1])
            elif c=='restore': self.restore(i,e[1])
        return {'log':self.log,'state':self.state()}

def run_request(req):
    return {'runs':[RefEngine(r).run(r['events']) for r in req['runs']]}
